use crate::average;

/// One-line summary like "3 values, mean 2.00".
pub fn report(values: &[f64]) -> String {
    match average(values) {
        Some(mean) => format!("{} values, mean {:.2}", values.len(), mean),
        None => format!("{} values, mean n/a", values.len()),
